INSERT INTO "days" VALUES('2026-11-12','2026-11-12 00:00 → 本条记录更新时间（上海时间）','核对发现公开页仍停在 11 月 11 日的快照。按要求把任务从建立日到今天的记录补齐、脱敏，并重新发布。记忆库仍然只是本机命令行，这一轮没有做成 MCP 或 skill。','[{"repo": "yhyu13/agent-work-log", "work": "补上 11 月 10 日、11 日、12 日三条每日记录。每条包含总结、当日工作和当日 MR，并写明记录更新时间与每条 MR 的更新时间。", "status": "本次发布。个人主页仓库没有改，Agent Lab 仍未提交。", "evidence": "发布后以线上 latest.json 的 updatedAt、天数和 PR 数为准。"}, {"repo": "UnifiedAgentMemory", "work": "确认现有入口是本机 memory.py 的 search / inject。inject 只返回已批准经验，目前没有已批准条目。", "status": "没有新建 MCP，也没有新建 skill。", "evidence": "本机 CLI 与 sqlite。公开库仍是只读投影。"}]','2026-11-12T14:45:32+00:00','[{"repo": "yhyu13/yhyu13.github.io", "number": 24, "title": "fix(decks): stop asserting a disputed guest name on the Huberman deck", "state": "merged", "url": "https://github.com/yhyu13/yhyu13.github.io/pull/24", "updated_at": "2026-11-12T14:39:02Z", "merged_at": "2026-11-12T14:39:02Z"}, {"repo": "yhyu13/AgentSkillsVault", "number": 30, "title": "feat(skills): multi-agent-repo-governance v1.2.0 — the seven gate self-blocking traps", "state": "merged", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/30", "updated_at": "2026-11-12T14:38:47Z", "merged_at": "2026-11-12T14:38:45Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 193, "title": "feat(005): profiles 表与三接口 + 四支开场台词", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/193", "updated_at": "2026-11-12T14:35:43Z", "merged_at": "2026-11-12T14:35:43Z"}, {"repo": "yhyu13/yhyu13.github.io", "number": 23, "title": "feat(decks): add seven video slides and two release-hosted cuts", "state": "merged", "url": "https://github.com/yhyu13/yhyu13.github.io/pull/23", "updated_at": "2026-11-12T14:35:21Z", "merged_at": "2026-11-12T14:35:21Z"}, {"repo": "yhyu13/AgentSkillsVault", "number": 29, "title": "feat(skills): 从 个人成长 产物装 7 个 skill（含父/子引用自包含修复）", "state": "merged", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/29", "updated_at": "2026-11-12T14:30:36Z", "merged_at": "2026-11-12T14:30:36Z"}, {"repo": "yhyu13/wuxia-town", "number": 7, "title": "docs(prd-roi): 5-day plan + 24x7 model + Agent ROI measurement matrix", "state": "open", "url": "https://github.com/yhyu13/wuxia-town/pull/7", "updated_at": "2026-11-12T14:21:39Z", "merged_at": null}, {"repo": "ailiaixue/pbl", "number": 204, "title": "feat(public): 三处页脚挂上 ICP 备案信息（沪ICP备2026006879号）", "state": "open", "url": "https://github.com/ailiaixue/pbl/pull/204", "updated_at": "2026-11-12T14:19:07Z", "merged_at": null}, {"repo": "ailiaixue/pbl", "number": 209, "title": "feat(safety): AI 聊天会话归属/求助信号/额度原子占额/请求幂等 + 会话空闲超时（E01-E04）", "state": "closed", "url": "https://github.com/ailiaixue/pbl/pull/209", "updated_at": "2026-11-12T13:58:25Z", "merged_at": null}, {"repo": "ailiaixue/pbl", "number": 262, "title": "fix(ci): lowgrade 装中文字体，字宽断言恢复可信（Refs #258）", "state": "closed", "url": "https://github.com/ailiaixue/pbl/pull/262", "updated_at": "2026-11-12T13:57:33Z", "merged_at": null}, {"repo": "yhyu13/PullYourselfUpApp", "number": 194, "title": "feat(005): 三问引导 + 每题回执 + 可验证承诺区", "state": "open", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/194", "updated_at": "2026-11-12T10:59:33Z", "merged_at": null}, {"repo": "yhyu13/PullYourselfUpApp", "number": 192, "title": "docs(spec): 竞品引导层调研 + 005 引导层 spec/plan + PRD 增补", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/192", "updated_at": "2026-11-12T10:31:03Z", "merged_at": "2026-11-12T10:31:03Z"}, {"repo": "yhyu13/wuxia-town", "number": 14, "title": "fix(visible): night lanterns, open south gate, hero follows patches", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/14", "updated_at": "2026-11-12T03:55:14Z", "merged_at": "2026-11-12T03:55:14Z"}, {"repo": "yhyu13/wuxia-town", "number": 11, "title": "chore(hero-assets): self-contained deliverables with pagoda + dynamic asset inlining", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/11", "updated_at": "2026-11-11T17:06:16Z", "merged_at": "2026-11-11T17:06:12Z"}, {"repo": "yhyu13/wuxia-town", "number": 10, "title": "feat(mechanism): generic planId hero asset replacement", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/10", "updated_at": "2026-11-11T16:31:15Z", "merged_at": "2026-11-11T16:31:03Z"}]');
INSERT INTO "lessons" VALUES('M-0001','统一记忆库必须先于公开投影','cross-repo','先做 Agent Lab 公开页，但跨 repo 经验仍散在聊天/PR/deliverables，无法稳定回注下一轮。','个人 Agent 的核心基础设施是统一记忆库；公开页、周报、Decision Tree 都只能做脱敏投影。先建正本，再做展示。','多 repo、多会话、需要长期自我迭代时。','单次一次性任务不需要统一记忆库。','candidate','observed','conversation','2026-11-11 user correction: 我需要的就是一个统一的记忆库','memory,architecture,priority');
INSERT INTO "lessons" VALUES('M-0002','批准声明不等于真实授权','yhyu13.github.io','JSON 中 approved/autoPublish 字段可能被页面误读为本人已批准和发布系统可用。','批准元数据只能证明声明完整；真实授权必须来自本人消息或工具回执。页面不得把声明写成已批准或可自动发布。','公开记录、自动发布、规则采用。','无。','candidate','observed','code/test','AgentLabPage.tsx / agentLabSchema.mjs / agent-lab.spec.ts','approval,publication,safety');
INSERT INTO "lessons" VALUES('M-0003','实测指标必须有有限值、样本、方法和证据','cross-repo','未测量值可能被填 0，或非有限数/缺样本被包装成收益。','measured/estimated 必须有限数值、单位、方法、正整数样本量、证据引用；时间 ROI 必须有正分母。未测量/不可比保持 null。','ROI、实验结果、公开指标。','探索性笔记可写假设，但不能标 measured。','candidate','observed','code/test','agentLabSchema.mjs / check-agent-lab.test.mjs','metrics,roi,truth');
INSERT INTO "lessons" VALUES('M-0004','合并授权必须绑定实时 PR head','AgentSkillsVault','旧批准可能被新提交复用，导致未经重新审查的合并。','绿黄红分级和合并批准必须绑定当前 PR head、检查项和批准主体；head 变化即失效。','多 Agent PR、自动合并、治理模板。','只读调查不需要合并授权。','candidate','observed','commit/PR','AgentSkillsVault e791537 / PR #21','governance,pr,approval');
INSERT INTO "lessons" VALUES('M-0005','引用检查要分范围，避免误判断链','AgentSkillsVault','ref gate 把源仓路径、模板路径、SKILL.md 引用混在一起检查，产生误报。','check_refs.py 管 SKILL.md 契约引用；治理检查管 repo docs；模板用 glob 解析，不写死 tier 路径。','skill vault、模板仓、多目录引用。','单一简单 docs 仓可简化。','candidate','observed','commit','AgentSkillsVault 2c033bf / 6f48d96 / 626cd2a','refcheck,ci,skills');
INSERT INTO "lessons" VALUES('M-0006','测试服部署不等于生产上线','pbl','语音输入修复部署到测试服后，容易被误报为生产已更新。','汇报必须分开测试服/生产版本、head、worker 状态；生产未动就明确写未动。','多环境部署、用户验收。','无。','candidate','observed','task digest','AI_Turtor/pbl session 77fda2bf: test v1.7.22.92, prod v1.7.22.91','deployment,truth,pbl');
INSERT INTO "lessons" VALUES('M-0007','Pad/输入法问题要真机验收和前后证据','pbl','语音转写、输入法 composition、课堂布局容易发一版修一层。','Pad 类改动要求真机验收清单；issue 中补修复前后截图/录屏证据；独立对抗测试后再收尾。','移动端输入、课堂 UI、语音转写。','纯后端逻辑可用自动化测试为主。','candidate','observed','commit/PR/issue','pbl #266 / #278 / #279','mobile,acceptance,evidence');
INSERT INTO "lessons" VALUES('M-0008','CI 绿不等于可合并，独立审查可 BLOCKED','Aholo_Hackthon','PR CI 通过但来源所有权/历史引用/审查阻塞未解决。','独立审查必须能 BLOCKED；CI 只是必要条件。历史引用要区分历史快照和现行依据，来源所有权要登记。','比赛仓、文档退役、多 PR 审查。','无。','candidate','observed','commit/PR comment','Aholo_Hackthon spec-008 / PR #130 #131 #132 GRADE','review,ci,ownership');
INSERT INTO "lessons" VALUES('M-0009','研究产物先隔离，论文说法回原文核对','SimCity','AI 模拟/知识库研究可能污染 repo，或把二手说法当事实。','研究脚本和产物放临时目录；论文阈值/频率等回原文核对；未写入 repo 就不说 repo 已更新。','研究型任务、外部论文、沙盒复刻。','明确要入库的实现任务除外。','candidate','observed','task digest','SimCity session ccd15cfd: [temp dir] paper §4.2 threshold 150','research,isolation,truth');
INSERT INTO "lessons" VALUES('M-0010','大媒体长期走 Release，公开页走 lazy/budget/schema','yhyu13.github.io','MP4 进 Git 历史会撑大仓库；公开页可能增大首页入口或渲染坏数据。','同类视频多了改走 GitHub Release；公开页 lazy route、entry budget、运行时 schema、未知字段拒绝。','GitHub Pages、媒体资产、公开数据页。','小图标/短期演示可暂存 git。','candidate','observed','task digest/code','homepage PR #22 / Agent Lab build 294.52kB','pages,media,performance,schema');
